80:   cargarGruposDeEspacioAcademico(espacioAcademico: any, index: number): void {
81:     const periodoId = this.infoGrupoEstudio.periodo.Id;
82:     this.espacioAcademicoService
83:       .get(
84:         `espacio-academico?query=activo:true,periodo_id:${periodoId},espacio_academico_padre:${espacioAcademico._id}`
85:       )
86:       .subscribe((res: any) => {
87:         if (res.Success && res.Data.length > 0) {
88:           this.gruposDeEspacioAcademico[index] = res.Data;
89:         } else {
90:           this.popUpManager.showAlert(
