187:       const grupoForm = this.listaEspaciosGrupos.at(index) as FormGroup;
188:       grupoForm.get('grupo')?.reset();
189:       return this.popUpManager.showAlert(
190:         '',
191:         this.translate.instant(
192:           'gestion_horarios.espacio_ya_esta_en_otro_grupo_estudio'
