761:       if (!solicitudId) {
762:         continue;
763:       }
764: 
765:       const existing = latestByIdSolicitud.get(solicitudId);
766:       if (!existing || new Date(item.FechaCreacion) > new Date(existing.FechaCreacion)) {
767:         latestByIdSolicitud.set(solicitudId, item);
